function vitalstack_ai_dictionary_url() {
	$page = get_page_by_path( 'ai-dictionary' );
	return $page ? get_permalink( $page ) : home_url( '/ai-dictionary/' );
}

function vitalstack_ai_dictionary_assets() {
	if ( ! is_page_template( 'page-ai-dictionary.php' ) ) {
		return;
	}
	wp_enqueue_script( 'vitalstack-nova', vitalstack_asset_url( 'assets/js/nova.js' ), array(), VITALSTACK_VERSION, array( 'in_footer' => true, 'strategy' => 'defer' ) );
	wp_enqueue_script( 'vitalstack-ai-dictionary', vitalstack_asset_url( 'assets/js/ai-dictionary.js' ), array( 'vitalstack-nova' ), VITALSTACK_VERSION, array( 'in_footer' => true, 'strategy' => 'defer' ) );
}
add_action( 'wp_enqueue_scripts', 'vitalstack_ai_dictionary_assets', 26 );
